// Fundamental Types and Qualifiers
const int MAX_USERS = 50;
volatile float temp_sensor;
unsigned long long system_time;

// Storage Classes
static char shared_buffer[1024];
extern int global_counter;
register short quick_index;

// Derived Types: Pointers and Arrays
int* data_ptr = NULL;
char name[32] = "C Reference";
void (*callback_func)(int); // Function pointer

// User-defined Types (Struct/Typedef)
typedef struct {
    int x;
    int y;
} Point2D;

Point2D origin;

// Enumeration
enum State { READY, ACTIVE, ERROR };
enum State current_state;
